<template><q-page class="page"><p class="eyebrow">ADMINISTRAÇÃO</p><h1>Revisar questões</h1><p class="copy">Valide alternativas e publique somente questões revisadas.</p><q-banner v-if="error" rounded class="error">{{ error }}</q-banner><q-inner-loading :showing="loading" color="primary"/><q-list v-if="questions.length" bordered separator class="list"><q-expansion-item v-for="question in questions" :key="question.id" :label="question.statement"><q-card flat><q-card-section><p v-for="option in question.options" :key="option.id"><strong>{{option.label}}.</strong> {{option.content}}</p><q-btn unelevated no-caps color="primary" label="Publicar questão" :loading="publishing===question.id" @click="publish(question.id)"/></q-card-section></q-card></q-expansion-item></q-list><q-card v-else-if="!loading" flat class="empty"><q-card-section>Nenhum rascunho pendente de revisão.</q-card-section></q-card></q-page></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import type{PublishedQuestion}from'../../../Domain/QuestionBank/QuestionRepository';import{getPage,postData}from'../../../Infrastructure/Http/AxiosApiClient';const questions=ref<readonly PublishedQuestion[]>([]);const loading=ref(false);const publishing=ref('');const error=ref('');async function load(){loading.value=true;try{questions.value=(await getPage<PublishedQuestion>('/admin/questions/drafts')).items}catch(e){error.value=e instanceof Error?e.message:'Não foi possível carregar rascunhos.'}finally{loading.value=false}}async function publish(id:string){publishing.value=id;try{await postData('/admin/questions/'+id+'/publish');questions.value=questions.value.filter(q=>q.id!==id)}catch(e){error.value=e instanceof Error?e.message:'Não foi possível publicar.'}finally{publishing.value=''}}onMounted(load);</script>
<style scoped>.page{max-width:1000px;margin:auto;padding:42px 34px}.eyebrow{color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.page h1{color:#142950;margin:0}.copy{color:#71819e}.list,.empty{background:#fff;border:1px solid #e5ecf6;border-radius:16px;overflow:hidden}.error{margin:16px 0;background:#fff3f2;color:#ae2f25}.q-card p{padding:8px;background:#f6f8fc;border-radius:8px}.q-btn{margin-top:12px}</style>
